{"files":[{"path":"lib/lore/certify.ts","content":"/**
 * sIVM certification worker: given a column's v_from -> v_to edit, decide
 * which cached v_from cells can be reused as v_to values with expected
 * false-reuse <= alpha (w.p. >= 1-delta), sampling only what the bound needs.
 *
 * The oracle (fresh v_to computation for sampled rows) is injectable so
 * experiments can serve it from a precomputed ground-truth table while
 * production serves it from the live runner. Every oracle call is counted;
 * that count IS the verification cost.
 */
import { randomUUID } from "node:crypto";
import {
  adaptiveCertifyStratum,
  assignStrata,
  diffPrompts,
  planSampleSizes,
  seededShuffle,
  selectReuse,
  type PromptDeltaV1,
  type SivmCellInput,
  type StratumResult,
} from "@lore/core/sivm";
import {
  applyCertificateReuse,
  getCellsForVersion,
  getColumnVersion,
  saveCertificate,
  type AiColumn,
} from "./column-store";
import { bindTemplate } from "./run-column";

type Row = Record<string, unknown>;

/** Returns fresh v_to values for the requested rows. */
export type Oracle = (rowIds: string[]) => Promise<Map<string, unknown>>;

export interface CertifyOptions {
  alpha: number;
  delta: number;
  /** Deterministic seed for the stratified sample (reproducibility). */
  seed?: number;
  /** Persist certificate + apply reuse rows (off for experiments). */
  apply?: boolean;
  /**
   * Grid-adaptive sampling: peek at a doubling look schedule (delta split
   * across looks, so peeking stays valid), stop early on certify or
   * futility. Unlocks small alpha without paying the worst-case sample.
   */
  adaptive?: boolean;
  /** Look-schedule depth for adaptive mode (default 4: 45/90/180/360). */
  maxLooks?: number;
  /**
   * Custom stratifier (e.g. embedding-interaction buckets). Must be frozen
   * before sampling; stratifier quality affects power only, never validity.
   */
  stratifier?: (
    cells: SivmCellInput[],
    delta: PromptDeltaV1,
  ) => ReturnType<typeof assignStrata>;
  /** Guarantee target: user-facing presented cells (default) or the strict
   * unsampled reuse set (deflated threshold). */
  estimand?: "presented" | "reuse-set";
}

export interface CertifyOutcome {
  certificateId: string;
  delta: PromptDeltaV1;
  strata: StratumResult[];
  sampledRowIds: string[];
  reusedRowIds: string[];
  recomputeRowIds: string[];
  oracleCalls: number;
  /** Sampled rows whose fresh value disagreed with cache (by stratum). */
  observedFlips: number;
}

function equivalent(a: unknown, b: unknown): boolean {
  // v1 equivalence: exact for booleans/selects/numbers-as-emitted; the
  // free-text judge path is a Phase 3 upgrade with its own calibrated error.
  return JSON.stringify(a) === JSON.stringify(b);
}

export async function verifyColumnEdit(
  column: AiColumn,
  fromVersion: number,
  toVersion: number,
  rows: Row[],
  idField: string,
  oracle: Oracle,
  opts: CertifyOptions,
): Promise<CertifyOutcome> {
  const vFrom = await getColumnVersion(column.id, fromVersion);
  const vTo = await getColumnVersion(column.id, toVersion);
  if (!vFrom || !vTo) throw new Error("missing column version");

  const delta = diffPrompts(vFrom.prompt_template, vTo.prompt_template);

  const rowById = new Map(rows.map((r) => [String(r[idField]), r]));
  const cached = await getCellsForVersion(column.id, fromVersion, [
    ...rowById.keys(),
  ]);
  const usable = cached.filter(
    (c) => (c.status === "done" || c.status === "cached") && rowById.has(c.row_id),
  );

  // Freeze strata from v_from cache + the prompt delta (pre-sampling).
  const inputs: SivmCellInput[] = usable.map((c) => ({
    rowId: c.row_id,
    cachedValue: c.value,
    boundText: bindTemplate(vFrom.prompt_template, rowById.get(c.row_id)!)
      .text,
  }));
  const strata = (opts.stratifier ?? assignStrata)(inputs, delta);
  const plan = planSampleSizes(
    strata.map((s) => ({ id: s.id, size: s.rowIds.length })),
    opts.alpha,
    opts.delta,
  );

  // Stratified deterministic sample order.
  const seed = opts.seed ?? 42;
  const cacheByRow = new Map(usable.map((c) => [c.row_id, c.value]));
  const fresh = new Map<string, unknown>();
  const revealed = new Set<string>();
  const reveal = async (rowIds: string[]) => {
    const need = rowIds.filter((id) => !revealed.has(id));
    if (need.length > 0) {
      const got = await oracle(need);
      for (const [k, v] of got) fresh.set(k, v);
      for (const id of need) revealed.add(id);
    }
  };

  let results: StratumResult[];
  const sampledByStratum = new Map<string, string[]>();

  if (opts.adaptive) {
    const K = Math.max(1, strata.length);
    const perStratumDelta = opts.delta / K;
    results = [];
    for (const s of strata) {
      const order = seededShuffle(s.rowIds, seed);
      const outcome = await adaptiveCertifyStratum(
        s.rowIds.length,
        opts.alpha,
        perStratumDelta,
        async (n) => {
          const prefix = order.slice(0, n);
          await reveal(prefix);
          return prefix
            .filter((id) => fresh.has(id))
            .map((id) =>
              equivalent(cacheByRow.get(id), fresh.get(id)) ? 0 : 1,
            );
        },
        45,
        opts.maxLooks ?? 4,
        opts.estimand ?? "presented",
      );
      sampledByStratum.set(s.id, order.slice(0, outcome.sampled));
      const last = outcome.looks[outcome.looks.length - 1]!;
      results.push({
        stratumId: s.id,
        size: s.rowIds.length,
        sampled: outcome.sampled,
        flips: last.flips,
        empiricalFlipRate: last.n > 0 ? last.flips / last.n : 1,
        upperBound: last.upperBound,
        certified: outcome.certified,
      });
    }
  } else {
    for (const s of strata) {
      const take = plan.get(s.id) ?? 0;
      sampledByStratum.set(s.id, seededShuffle(s.rowIds, seed).slice(0, take));
    }
    await reveal([...sampledByStratum.values()].flat());
    const mathInput = strata.map((s) => ({
      id: s.id,
      size: s.rowIds.length,
      flipSample: (sampledByStratum.get(s.id) ?? []).flatMap((rowId) => {
        if (!fresh.has(rowId)) return [];
        return [equivalent(cacheByRow.get(rowId), fresh.get(rowId)) ? 0 : 1];
      }),
    }));
    results = selectReuse({
      strata: mathInput,
      alpha: opts.alpha,
      delta: opts.delta,
    });
  }
  const sampledRowIds = [...sampledByStratum.values()].flat();

  const certifiedIds = new Set(
    results.filter((r) => r.certified).map((r) => r.stratumId),
  );
  const sampledSet = new Set(sampledRowIds);
  const reusedRowIds: string[] = [];
  const recomputeRowIds: string[] = [];
  for (const s of strata) {
    for (const rowId of s.rowIds) {
      // Sampled rows are already freshly computed - they are neither reused
      // nor recomputed again.
      if (sampledSet.has(rowId)) continue;
      if (certifiedIds.has(s.id)) reusedRowIds.push(rowId);
      else recomputeRowIds.push(rowId);
    }
  }

  const certificateId = randomUUID();
  if (opts.apply) {
    await saveCertificate({
      id: certificateId,
      columnId: column.id,
      fromVersion,
      toVersion,
      alpha: opts.alpha,
      delta,
      strata: results,
      reusedCount: reusedRowIds.length,
      recomputeCount: recomputeRowIds.length,
      sampledCount: sampledRowIds.length,
      verificationCostUsd: 0,
    });
    await applyCertificateReuse(
      column.id,
      fromVersion,
      toVersion,
      column.model,
      reusedRowIds,
      certificateId,
    );
  }

  return {
    certificateId,
    delta,
    strata: results,
    sampledRowIds,
    reusedRowIds,
    recomputeRowIds,
    oracleCalls: revealed.size,
    observedFlips: results.reduce((a, r) => a + r.flips, 0),
  };
}

export { verifyColumnEdit as certifyColumnEdit };
"},{"path":"app/api/lore/columns/[id]/certify/route.ts","content":"import { NextResponse } from "next/server";
import { z } from "zod";
import type { FilterSpec } from "@lore/core";
import { adapterFor, type BackendId } from "@/lib/lore/adapters";
import { certifyColumnEdit } from "@/lib/lore/certify";
import {
  getCellsForVersion,
  getColumn,
  getColumnVersion,
  recordLedger,
} from "@/lib/lore/column-store";
import { PROFILE_ID_FIELD } from "@/lib/lore/fields";
import { runColumn } from "@/lib/lore/run-column";

const BodySchema = z.object({
  filter: z.custom<FilterSpec>().optional(),
  backend: z.enum(["elasticsearch", "mysql", "hybrid"]).default("mysql"),
  alpha: z.number().min(0.01).max(0.5).default(0.1),
  delta: z.number().min(0.01).max(0.5).default(0.1),
  /** Scope cap: how many rows of the current filter the certificate covers. */
  limit: z.number().int().min(50).max(2000).default(500),
});

/**
 * Production sIVM: certify reuse of the previous version's cached cells for
 * the current version over the given filter scope. The oracle is the live
 * runner (sampled rows get real fresh v_to computations, which also
 * materializes them). Certified rows get reused_certified cells; the rest
 * stay empty pending recompute.
 */
export async function POST(
  req: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params;
  const parsed = BodySchema.safeParse(await req.json());
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.message }, { status: 400 });
  }
  const column = await getColumn(id);
  if (!column) {
    return NextResponse.json({ error: "column not found" }, { status: 404 });
  }
  if (column.prompt_version < 2) {
    return NextResponse.json(
      { error: "no previous version to reuse from" },
      { status: 400 },
    );
  }
  const fromVersion = column.prompt_version - 1;
  const toVersion = column.prompt_version;
  const vTo = await getColumnVersion(id, toVersion);
  if (!vTo) {
    return NextResponse.json({ error: "version missing" }, { status: 500 });
  }

  try {
    const adapter = adapterFor(parsed.data.backend as BackendId);
    const filter: FilterSpec = parsed.data.filter ?? {
      schemaVersion: 1,
      all: [],
    };
    const page = await adapter.search(filter, { limit: parsed.data.limit });
    const rows = page.rows;
    const rowById = new Map(
      rows.map((r) => [String(r[PROFILE_ID_FIELD]), r]),
    );

    const outcome = await certifyColumnEdit(
      column,
      fromVersion,
      toVersion,
      rows,
      PROFILE_ID_FIELD,
      async (rowIds) => {
        // Live oracle: really compute v_to for the sample.
        const sampleRows = rowIds
          .map((rid) => rowById.get(rid))
          .filter((r): r is NonNullable<typeof r> => r !== undefined);
        await runColumn(column, sampleRows, PROFILE_ID_FIELD, {
          concurrency: 8,
          versionOverride: {
            promptTemplate: vTo.prompt_template,
            promptVersion: toVersion,
          },
        });
        const fresh = (
          await getCellsForVersion(column.id, toVersion, rowIds)
        ).filter((c) => c.status === "done" || c.status === "cached");
        return new Map(fresh.map((c) => [c.row_id, c.value]));
      },
      {
        alpha: parsed.data.alpha,
        delta: parsed.data.delta,
        apply: true,
      },
    );

    await recordLedger({
      kind: "verify",
      columnId: column.id,
      model: column.model,
      cells: outcome.oracleCalls,
      inputTokens: 0,
      outputTokens: 0,
      costUsd: 0,
    });

    return NextResponse.json({
      certificateId: outcome.certificateId,
      scope: rows.length,
      sampled: outcome.oracleCalls,
      reused: outcome.reusedRowIds.length,
      recompute: outcome.recomputeRowIds.length,
      observedFlips: outcome.observedFlips,
      strata: outcome.strata,
      alpha: parsed.data.alpha,
    });
  } catch (err) {
    console.error("certify error", err);
    return NextResponse.json(
      { error: err instanceof Error ? err.message : "certify failed" },
      { status: 500 },
    );
  }
}
"}],"concerns":["app/api/lore/columns/[id]/certify/route.ts still imports certifyColumnEdit; per the instruction to change only lib/lore/certify.ts I added a deprecated alias for that symbol in lib/lore/certify.ts so the build stays green. Once the route import is updated to verifyColumnEdit, the alias can be removed."],"rationale":"Renamed the primary exported function to verifyColumnEdit and kept a deprecated alias in lib/lore/certify.ts so the existing route import compiles without editing additional files."}

{"files":[{"path":"lib/chat/provisional-chat.ts","content":"const PENDING_CHAT_STORAGE_MAX_AGE_MS = 10 * 60 * 1000;
const PENDING_CHAT_STORAGE_PREFIX = "eve-chat-pending:";
const PROVISIONAL_CHAT_ID_PREFIX = "new-";

type StoredPendingChat = {
  readonly createdAt: number;
  readonly pendingUserMessage: string;
  readonly version: 1;
};

export function makeProvisionalChatId() {
  const randomId =
    globalThis.crypto?.randomUUID?.() ??
    `${Date.now()}-${Math.random().toString(36).slice(2)}`;

  return `${PROVISIONAL_CHAT_ID_PREFIX}${randomId}`;
}

/**
 * Deprecated alias kept for backward compatibility.
 *
 * Existing callers (e.g. app/_components/home-chat-page.tsx) still import
 * `createProvisionalChatId`, so this alias is retained to keep the repository
 * building cleanly until all call sites migrate to `makeProvisionalChatId`.
 */
export const createProvisionalChatId = makeProvisionalChatId;

export function isProvisionalChatId(chatId: string) {
  return chatId.startsWith(PROVISIONAL_CHAT_ID_PREFIX);
}

export function writePendingChatMessage(chatId: string, message: string) {
  const pendingUserMessage = message.trim();

  if (!pendingUserMessage || typeof window === "undefined") {
    return false;
  }

  try {
    window.sessionStorage.setItem(
      getPendingChatStorageKey(chatId),
      JSON.stringify({
        createdAt: Date.now(),
        pendingUserMessage,
        version: 1,
      } satisfies StoredPendingChat),
    );
    return true;
  } catch {
    return false;
  }
}

export function readPendingChatMessage(chatId: string) {
  if (typeof window === "undefined") {
    return null;
  }

  const key = getPendingChatStorageKey(chatId);
  const stored = window.sessionStorage.getItem(key);

  if (!stored) {
    return null;
  }

  try {
    const parsed = JSON.parse(stored) as Partial<StoredPendingChat>;
    const createdAt = Number(parsed.createdAt);
    const pendingUserMessage = parsed.pendingUserMessage?.trim();

    if (
      !pendingUserMessage ||
      !Number.isFinite(createdAt) ||
      Date.now() - createdAt > PENDING_CHAT_STORAGE_MAX_AGE_MS
    ) {
      window.sessionStorage.removeItem(key);
      return null;
    }

    return pendingUserMessage;
  } catch {
    window.sessionStorage.removeItem(key);
    return null;
  }
}

export function clearPendingChatMessage(chatId: string) {
  if (typeof window === "undefined") {
    return;
  }

  window.sessionStorage.removeItem(getPendingChatStorageKey(chatId));
}

function getPendingChatStorageKey(chatId: string) {
  return `${PENDING_CHAT_STORAGE_PREFIX}${chatId}`;
}
"}],"concerns":["Strictly removing `createProvisionalChatId` without updating `app/_components/home-chat-page.tsx` would break the build, so the old name is retained as a deprecated alias to keep the repository building cleanly."],"rationale":"Renamed the implementation to makeProvisionalChatId while retaining createProvisionalChatId as a deprecated alias to keep the build clean."}

{"files":[{"path":"lib/rate-limit.ts","content":"import { Redis } from "@upstash/redis";

type LimitOptions = {
  readonly key: string;
  readonly limit: number;
  readonly prefix: string;
  readonly windowSeconds: number;
};

export class RateLimitError extends Error {
  readonly retryAfter: number;

  constructor(retryAfter: number) {
    super("Too many requests. Please wait a moment and try again.");
    this.retryAfter = retryAfter;
  }
}

let redis: Redis | null | undefined;

function getRedisEnv() {
  const url = process.env.UPSTASH_REDIS_REST_URL?.trim() || process.env.KV_REST_API_URL?.trim();
  const token =
    process.env.UPSTASH_REDIS_REST_TOKEN?.trim() || process.env.KV_REST_API_TOKEN?.trim();

  return url && token ? { token, url } : null;
}

function getRedis() {
  if (redis !== undefined) {
    return redis;
  }

  const env = getRedisEnv();

  if (!env) {
    redis = null;
    return redis;
  }

  redis = new Redis(env);
  return redis;
}

export async function imposeRateLimit(options: LimitOptions) {
  const client = getRedis();

  if (!client) {
    return;
  }

  const now = Math.floor(Date.now() / 1000);
  const windowId = Math.floor(now / options.windowSeconds);
  const redisKey = `rate:${options.prefix}:${options.key}:${windowId}`;
  const count = await client.incr(redisKey);

  if (count === 1) {
    await client.expire(redisKey, options.windowSeconds);
  }

  if (count > options.limit) {
    const retryAfter = options.windowSeconds - (now % options.windowSeconds);
    throw new RateLimitError(retryAfter);
  }
}

/**
 * Deprecated alias for backwards compatibility.
 * Use `imposeRateLimit` for new code.
 * @deprecated Use imposeRateLimit instead.
 */
export const enforceRateLimit = imposeRateLimit;
"}],"concerns":["A pure rename removing enforceRateLimit would break existing callers and violate the clean-build requirement, so enforceRateLimit was kept as a deprecated alias alongside imposeRateLimit."],"rationale":"Introduced imposeRateLimit as the canonical export while keeping enforceRateLimit as a deprecated alias to keep the build clean."}

{"files":[{"path":"lib/password-auth.ts","content":"import { createHash, createHmac, timingSafeEqual } from "node:crypto";

export const PASSWORD_SESSION_COOKIE_NAME = "eve_chat_session";
export const PASSWORD_SESSION_MAX_AGE = 60 * 60 * 24 * 30;

const TOKEN_VERSION = "v1";

export function getChatPassword() {
  return process.env.EVE_CHAT_PASSWORD?.trim() ?? "";
}

export function verifyChatPassword(candidate: string) {
  const expected = getChatPassword();

  if (!expected) {
    return false;
  }

  return timingSafeEqual(hash(candidate), hash(expected));
}

export function makePasswordSessionToken(now = Date.now()) {
  const expiresAt = Math.floor(now / 1000) + PASSWORD_SESSION_MAX_AGE;
  const payload = `${TOKEN_VERSION}.${expiresAt}`;
  const signature = sign(payload);

  return `${payload}.${signature}`;
}

export function verifyPasswordSessionToken(token: string | undefined, now = Date.now()) {
  if (!token) {
    return false;
  }

  const [version, expiresAtRaw, signature, ...extra] = token.split(".");
  const expiresAt = Number(expiresAtRaw);

  if (
    version !== TOKEN_VERSION ||
    !signature ||
    extra.length > 0 ||
    !Number.isSafeInteger(expiresAt) ||
    expiresAt <= Math.floor(now / 1000)
  ) {
    return false;
  }

  const expected = sign(`${version}.${expiresAt}`);

  return timingSafeEqual(hash(signature), hash(expected));
}

export function getPasswordSessionFromHeaders(headers: Headers) {
  const cookieHeader = headers.get("cookie");

  if (!cookieHeader) {
    return false;
  }

  const token = cookieHeader
    .split(";")
    .map((cookie) => cookie.trim().split("="))
    .find(([name]) => name === PASSWORD_SESSION_COOKIE_NAME)?.[1];

  return verifyPasswordSessionToken(token ? decodeURIComponent(token) : undefined);
}

export function hasSameOriginRequest(request: Request) {
  const origin = request.headers.get("origin");
  const publicHost =
    request.headers.get("x-forwarded-host") ??
    request.headers.get("host");

  if (!origin || !publicHost) {
    return false;
  }

  try {
    const originUrl = new URL(origin);
    const forwardedProtocol = request.headers.get("x-forwarded-proto");

    return (
      originUrl.host === publicHost &&
      (!forwardedProtocol || originUrl.protocol === `${forwardedProtocol}:`)
    );
  } catch {
    return false;
  }
}

function hash(value: string) {
  return createHash("sha256").update(value).digest();
}

function sign(payload: string) {
  return createHmac("sha256", getChatPassword()).update(payload).digest("base64url");
}
