{"files":[{"path":"lib/lore/run-column.ts","content":"/**
 * The per-cell sub-agent runner: binds a column's prompt template to each
 * row, runs a typed structured-output call, and persists results with
 * caching, a cost ledger, and a pre-run estimate gate.
 *
 * Content hash covers ONLY the row fields the template actually binds — the
 * base of sIVM's cross-version reuse (an edit that adds a bound field changes
 * the hash population; an unrelated row field change does not).
 */
import { createHash } from "node:crypto";
import { generateObject } from "ai";
import { z } from "zod";
import type { ColumnOutputType, RunEstimate } from "@lore/core";
import {
  findCachedByHash,
  recordLedger,
  totalSpendUsd,
  writeCell,
  type AiColumn,
} from "./column-store";
import { CELL_DECODE, EXPERIMENT_BUDGET_USD, MODEL_PRICES } from "./models";

type Row = Record<string, unknown>;

// ---------------------------------------------------------------------------
// Template binding + content hash
// ---------------------------------------------------------------------------

const VAR_RE = /\{\{\s*([a-zA-Z0-9_]+)\s*\}\}/g;

export function templateFields(template: string): string[] {
  return [...template.matchAll(VAR_RE)].map((m) => m[1]!);
}

export function bindTemplateCore(
  template: string,
  row: Row,
): { text: string; contentHash: string } {
  const bound: Record<string, unknown> = {};
  const text = template.replaceAll(VAR_RE, (_, field: string) => {
    const v = row[field];
    bound[field] = v ?? null;
    if (v === null || v === undefined) return "(unknown)";
    return Array.isArray(v) ? v.join(", ") : String(v);
  });
  const contentHash = createHash("sha256")
    .update(JSON.stringify(bound))
    .digest("hex");
  return { text, contentHash };
}

// ---------------------------------------------------------------------------
// Output schema per column type (+ exact-shape example for budget models)
// ---------------------------------------------------------------------------

function valueSchema(spec: ColumnOutputType): z.ZodType {
  switch (spec.kind) {
    case "boolean":
      return z.boolean();
    case "number": {
      let n = z.number();
      if (spec.min !== undefined) n = n.min(spec.min);
      if (spec.max !== undefined) n = n.max(spec.max);
      return n;
    }
    case "select":
      return z.enum(spec.options as [string, ...string[]]);
    case "url":
      return z.string();
    case "json":
      return z.record(z.string(), z.unknown());
    case "text":
      return z.string();
  }
}

function exampleFor(spec: ColumnOutputType): string {
  const v =
    spec.kind === "boolean"
      ? "true"
      : spec.kind === "number"
        ? "7"
        : spec.kind === "select"
          ? JSON.stringify(spec.options[0])
          : '"short answer"';
  return `{"value":${v},"rationale":"one short sentence of evidence"}`;
}

function systemFor(spec: ColumnOutputType): string {
  return `You evaluate ONE row of a data table against the user's column
instruction. Judge only from the provided row data; if the data is
insufficient, still commit to the most defensible answer.
Return a JSON object with EXACTLY two keys: "value" and "rationale"
(<= 140 chars). ${
    spec.kind === "select"
      ? `"value" must be exactly one of: ${spec.options.map((o) => JSON.stringify(o)).join(", ")}.`
      : spec.kind === "boolean"
        ? `"value" must be a JSON boolean (true/false), not a string.`
        : spec.kind === "number"
          ? `"value" must be a JSON number${spec.min !== undefined || spec.max !== undefined ? ` between ${spec.min ?? "-inf"} and ${spec.max ?? "inf"}` : ""}.`
          : `"value" must be a string.`
  }
Example shape: ${exampleFor(spec)}`;
}

// ---------------------------------------------------------------------------
// Estimate + run
// ---------------------------------------------------------------------------

const EST_OVERHEAD_TOKENS = 160; // system + schema framing
const EST_OUTPUT_TOKENS = 60;

export function estimateRun(column: AiColumn, rows: Row[]): RunEstimate {
  const price = MODEL_PRICES[column.model] ?? { in: 1, out: 4 };
  let inputTokens = 0;
  for (const row of rows) {
    const { text } = bindTemplateCore(column.prompt_template, row);
    inputTokens += EST_OVERHEAD_TOKENS + Math.ceil(text.length / 4);
  }
  const outputTokens = rows.length * EST_OUTPUT_TOKENS;
  const estCostUsd =
    (inputTokens * price.in + outputTokens * price.out) / 1e6;
  return {
    rowCount: rows.length,
    estInputTokens: inputTokens,
    estOutputTokens: outputTokens,
    estCostUsd,
    requiresConfirmation: rows.length > 100 || estCostUsd > 0.5,
    ...(rows.length > 100 || estCostUsd > 0.5
      ? { reason: "over_absolute_threshold" as const }
      : {}),
  };
}

export interface RunResult {
  ran: number;
  cached: number;
  skipped: number;
  errors: number;
  costUsd: number;
  ms: number;
}

/** Tiny semaphore: bounded concurrency without a dependency. */
async function mapLimit<T, R>(
  items: T[],
  limit: number,
  fn: (item: T) => Promise<R>,
): Promise<R[]> {
  const results: R[] = new Array(items.length);
  let next = 0;
  const workers = Array.from(
    { length: Math.min(limit, items.length) },
    async () => {
      while (next < items.length) {
        const i = next++;
        results[i] = await fn(items[i]!);
      }
    },
  );
  await Promise.all(workers);
  return results;
}

export async function runColumn(
  column: AiColumn,
  rows: Row[],
  idField: string,
  opts?: {
    concurrency?: number;
    /** Run against a specific historical version (sIVM ground truth/verify). */
    versionOverride?: { promptTemplate: string; promptVersion: number };
  },
): Promise<RunResult> {
  const started = Date.now();
  const price = MODEL_PRICES[column.model] ?? { in: 1, out: 4 };
  if (opts?.versionOverride) {
    column = {
      ...column,
      prompt_template: opts.versionOverride.promptTemplate,
      prompt_version: opts.versionOverride.promptVersion,
    };
  }

  // Budget guard: never start a run that would push total spend past the cap.
  const est = estimateRun(column, rows);
  const spent = await totalSpendUsd();
  if (spent + est.estCostUsd > EXPERIMENT_BUDGET_USD) {
    throw new Error(
      `budget guard: $${spent.toFixed(2)} spent + $${est.estCostUsd.toFixed(2)} estimated exceeds the $${EXPERIMENT_BUDGET_USD} cap`,
    );
  }

  let ran = 0;
  let cached = 0;
  let errors = 0;
  let costUsd = 0;
  let inTok = 0;
  let outTok = 0;

  await mapLimit(rows, opts?.concurrency ?? 8, async (row) => {
    const rowId = String(row[idField]);
    const { text, contentHash } = bindTemplateCore(column.prompt_template, row);

    const hit = await findCachedByHash(
      column.id,
      column.prompt_version,
      column.model,
      contentHash,
    );
    if (hit) {
      if (hit.row_id !== rowId) {
        await writeCell({
          columnId: column.id,
          rowId,
          promptVersion: column.prompt_version,
          model: column.model,
          contentHash,
          status: "cached",
          value: hit.value,
          rationale: hit.rationale,
        });
      }
      cached++;
      return;
    }

    const t0 = Date.now();
    try {
      const res = await generateObject({
        model: column.model,
        schema: z.object({
          value: valueSchema(column.output_spec),
          rationale: z.string(),
        }),
        system: systemFor(column.output_spec),
        prompt: text,
        temperature: CELL_DECODE.temperature,
      });
      const cellIn = res.usage.inputTokens ?? 0;
      const cellOut = res.usage.outputTokens ?? 0;
      const cellCost = (cellIn * price.in + cellOut * price.out) / 1e6;
      inTok += cellIn;
      outTok += cellOut;
      costUsd += cellCost;
      await writeCell({
        columnId: column.id,
        rowId,
        promptVersion: column.prompt_version,
        model: column.model,
        contentHash,
        status: "done",
        value: res.object.value,
        rationale: res.object.rationale.slice(0, 500),
        inputTokens: cellIn,
        outputTokens: cellOut,
        costUsd: cellCost,
        latencyMs: Date.now() - t0,
      });
      ran++;
    } catch (err) {
      errors++;
      await writeCell({
        columnId: column.id,
        rowId,
        promptVersion: column.prompt_version,
        model: column.model,
        contentHash,
        status: "error",
        error: err instanceof Error ? err.message.slice(0, 800) : String(err),
        latencyMs: Date.now() - t0,
      });
    }
  });

  await recordLedger({
    kind: "run",
    columnId: column.id,
    model: column.model,
    cells: ran,
    inputTokens: inTok,
    outputTokens: outTok,
    costUsd,
  });

  return {
    ran,
    cached,
    skipped: 0,
    errors,
    costUsd,
    ms: Date.now() - started,
  };
}
"},{"path":"lib/lore/certify.ts","content":"/**
 * sIVM certification worker: given a column's v_from -> v_to edit, decide
 * which cached v_from cells can be reused as v_to values with expected
 * false-reuse <= alpha (w.p. >= 1-delta), sampling only what the bound needs.
 *
 * The oracle (fresh v_to computation for sampled rows) is injectable so
 * experiments can serve it from a precomputed ground-truth table while
 * production serves it from the live runner. Every oracle call is counted;
 * that count IS the verification cost.
 */
import { randomUUID } from "node:crypto";
import {
  adaptiveCertifyStratum,
  assignStrata,
  diffPrompts,
  planSampleSizes,
  seededShuffle,
  selectReuse,
  type PromptDeltaV1,
  type SivmCellInput,
  type StratumResult,
} from "@lore/core/sivm";
import {
  applyCertificateReuse,
  getCellsForVersion,
  getColumnVersion,
  saveCertificate,
  type AiColumn,
} from "./column-store";
import { bindTemplateCore } from "./run-column";

type Row = Record<string, unknown>;

/** Returns fresh v_to values for the requested rows. */
export type Oracle = (rowIds: string[]) => Promise<Map<string, unknown>>;

export interface CertifyOptions {
  alpha: number;
  delta: number;
  /** Deterministic seed for the stratified sample (reproducibility). */
  seed?: number;
  /** Persist certificate + apply reuse rows (off for experiments). */
  apply?: boolean;
  /**
   * Grid-adaptive sampling: peek at a doubling look schedule (delta split
   * across looks, so peeking stays valid), stop early on certify or
   * futility. Unlocks small alpha without paying the worst-case sample.
   */
  adaptive?: boolean;
  /** Look-schedule depth for adaptive mode (default 4: 45/90/180/360). */
  maxLooks?: number;
  /**
   * Custom stratifier (e.g. embedding-interaction buckets). Must be frozen
   * before sampling; stratifier quality affects power only, never validity.
   */
  stratifier?: (
    cells: SivmCellInput[],
    delta: PromptDeltaV1,
  ) => ReturnType<typeof assignStrata>;
  /** Guarantee target: user-facing presented cells (default) or the strict
   * unsampled reuse set (deflated threshold). */
  estimand?: "presented" | "reuse-set";
}

export interface CertifyOutcome {
  certificateId: string;
  delta: PromptDeltaV1;
  strata: StratumResult[];
  sampledRowIds: string[];
  reusedRowIds: string[];
  recomputeRowIds: string[];
  oracleCalls: number;
  /** Sampled rows whose fresh value disagreed with cache (by stratum). */
  observedFlips: number;
}

function equivalent(a: unknown, b: unknown): boolean {
  // v1 equivalence: exact for booleans/selects/numbers-as-emitted; the
  // free-text judge path is a Phase 3 upgrade with its own calibrated error.
  return JSON.stringify(a) === JSON.stringify(b);
}

export async function certifyColumnEdit(
  column: AiColumn,
  fromVersion: number,
  toVersion: number,
  rows: Row[],
  idField: string,
  oracle: Oracle,
  opts: CertifyOptions,
): Promise<CertifyOutcome> {
  const vFrom = await getColumnVersion(column.id, fromVersion);
  const vTo = await getColumnVersion(column.id, toVersion);
  if (!vFrom || !vTo) throw new Error("missing column version");

  const delta = diffPrompts(vFrom.prompt_template, vTo.prompt_template);

  const rowById = new Map(rows.map((r) => [String(r[idField]), r]));
  const cached = await getCellsForVersion(column.id, fromVersion, [
    ...rowById.keys(),
  ]);
  const usable = cached.filter(
    (c) => (c.status === "done" || c.status === "cached") && rowById.has(c.row_id),
  );

  // Freeze strata from v_from cache + the prompt delta (pre-sampling).
  const inputs: SivmCellInput[] = usable.map((c) => ({
    rowId: c.row_id,
    cachedValue: c.value,
    boundText: bindTemplateCore(vFrom.prompt_template, rowById.get(c.row_id)!)
      .text,
  }));
  const strata = (opts.stratifier ?? assignStrata)(inputs, delta);
  const plan = planSampleSizes(
    strata.map((s) => ({ id: s.id, size: s.rowIds.length })),
    opts.alpha,
    opts.delta,
  );

  // Stratified deterministic sample order.
  const seed = opts.seed ?? 42;
  const cacheByRow = new Map(usable.map((c) => [c.row_id, c.value]));
  const fresh = new Map<string, unknown>();
  const revealed = new Set<string>();
  const reveal = async (rowIds: string[]) => {
    const need = rowIds.filter((id) => !revealed.has(id));
    if (need.length > 0) {
      const got = await oracle(need);
      for (const [k, v] of got) fresh.set(k, v);
      for (const id of need) revealed.add(id);
    }
  };

  let results: StratumResult[];
  const sampledByStratum = new Map<string, string[]>();

  if (opts.adaptive) {
    const K = Math.max(1, strata.length);
    const perStratumDelta = opts.delta / K;
    results = [];
    for (const s of strata) {
      const order = seededShuffle(s.rowIds, seed);
      const outcome = await adaptiveCertifyStratum(
        s.rowIds.length,
        opts.alpha,
        perStratumDelta,
        async (n) => {
          const prefix = order.slice(0, n);
          await reveal(prefix);
          return prefix
            .filter((id) => fresh.has(id))
            .map((id) =>
              equivalent(cacheByRow.get(id), fresh.get(id)) ? 0 : 1,
            );
        },
        45,
        opts.maxLooks ?? 4,
        opts.estimand ?? "presented",
      );
      sampledByStratum.set(s.id, order.slice(0, outcome.sampled));
      const last = outcome.looks[outcome.looks.length - 1]!;
      results.push({
        stratumId: s.id,
        size: s.rowIds.length,
        sampled: outcome.sampled,
        flips: last.flips,
        empiricalFlipRate: last.n > 0 ? last.flips / last.n : 1,
        upperBound: last.upperBound,
        certified: outcome.certified,
      });
    }
  } else {
    for (const s of strata) {
      const take = plan.get(s.id) ?? 0;
      sampledByStratum.set(s.id, seededShuffle(s.rowIds, seed).slice(0, take));
    }
    await reveal([...sampledByStratum.values()].flat());
    const mathInput = strata.map((s) => ({
      id: s.id,
      size: s.rowIds.length,
      flipSample: (sampledByStratum.get(s.id) ?? []).flatMap((rowId) => {
        if (!fresh.has(rowId)) return [];
        return [equivalent(cacheByRow.get(rowId), fresh.get(rowId)) ? 0 : 1];
      }),
    }));
    results = selectReuse({
      strata: mathInput,
      alpha: opts.alpha,
      delta: opts.delta,
    });
  }
  const sampledRowIds = [...sampledByStratum.values()].flat();

  const certifiedIds = new Set(
    results.filter((r) => r.certified).map((r) => r.stratumId),
  );
  const sampledSet = new Set(sampledRowIds);
  const reusedRowIds: string[] = [];
  const recomputeRowIds: string[] = [];
  for (const s of strata) {
    for (const rowId of s.rowIds) {
      // Sampled rows are already freshly computed - they are neither reused
      // nor recomputed again.
      if (sampledSet.has(rowId)) continue;
      if (certifiedIds.has(s.id)) reusedRowIds.push(rowId);
      else recomputeRowIds.push(rowId);
    }
  }

  const certificateId = randomUUID();
  if (opts.apply) {
    await saveCertificate({
      id: certificateId,
      columnId: column.id,
      fromVersion,
      toVersion,
      alpha: opts.alpha,
      delta,
      strata: results,
      reusedCount: reusedRowIds.length,
      recomputeCount: recomputeRowIds.length,
      sampledCount: sampledRowIds.length,
      verificationCostUsd: 0,
    });
    await applyCertificateReuse(
      column.id,
      fromVersion,
      toVersion,
      column.model,
      reusedRowIds,
      certificateId,
    );
  }

  return {
    certificateId,
    delta,
    strata: results,
    sampledRowIds,
    reusedRowIds,
    recomputeRowIds,
    oracleCalls: revealed.size,
    observedFlips: results.reduce((a, r) => a + r.flips, 0),
  };
}
