export async function POST(request: Request) {
  const password = await request.text();

  if (!verifyChatPassword(password)) {
    return new Response("Unauthorized", { status: 401 });
  }

  const token = makePasswordSessionToken();

  return new Response("OK", {
    status: 200,
    headers: {
      "Set-Cookie": `${PASSWORD_SESSION_COOKIE_NAME}=${encodeURIComponent(token)}; Path=/; HttpOnly; SameSite=Strict; Max-Age=${PASSWORD_SESSION_MAX_AGE}`,
    },
  });
