{"files":[{"path":"lib/chat/local-store.ts","content":""use client";

import type { HandleMessageStreamEvent, SessionState } from "eve/client";
import { createFallbackTitle, DEFAULT_CHAT_TITLE } from "@/lib/chat/title";
import type { ActiveChat, ChatListItem } from "@/lib/chat/types";

const STORAGE_KEY = "eve-chat-template:chats";
const STORAGE_VERSION = 1;
const MAX_STORED_CHATS = 50;

type StoredChat = ActiveChat & {
  readonly updatedAt: string;
};

type StoredChatState = {
  readonly chats: readonly StoredChat[];
  readonly version: typeof STORAGE_VERSION;
};

export function listLocalChats(): ChatListItem[] {
  return readState().chats.map(toListItem);
}

export function getLocalChat(chatId: string): ActiveChat | null {
  const chat = readState().chats.find((item) => item.id === chatId);

  return chat ? toActiveChat(chat) : null;
}

export function createLocalChat(pendingUserMessage?: string) {
  const pendingMessage = pendingUserMessage?.trim() || null;
  const now = new Date().toISOString();
  const chat: StoredChat = {
    events: [],
    id: crypto.randomUUID(),
    pendingUserMessage: pendingMessage,
    session: undefined,
    title: pendingMessage ? createFallbackTitle(pendingMessage) : DEFAULT_CHAT_TITLE,
    updatedAt: now,
  };

  updateState((chats) => [chat, ...chats]);

  return toListItem(chat);
}

export function deleteLocalChat(chatId: string) {
  updateState((chats) => chats.filter((chat) => chat.id !== chatId));
}

export function markLocalChatPendingMessage(chatId: string, message: string) {
  const pendingMessage = message.trim();

  if (!pendingMessage) {
    throw new Error("Message cannot be empty.");
  }

  return updateChat(chatId, (chat) => ({
    ...chat,
    pendingUserMessage: pendingMessage,
    title:
      chat.title === DEFAULT_CHAT_TITLE
        ? createFallbackTitle(pendingMessage)
        : chat.title,
    updatedAt: new Date().toISOString(),
  }));
}

export function clearLocalChatPendingMessage(chatId: string) {
  updateChat(chatId, (chat) => ({
    ...chat,
    pendingUserMessage: null,
  }));
}

export function pushLocalChatEvent({
  chatId,
  event,
  eventIndex,
}: {
  readonly chatId: string;
  readonly event: HandleMessageStreamEvent;
  readonly eventIndex: number;
}) {
  updateChat(chatId, (chat) => {
    const events = [...chat.events];

    if (eventIndex >= events.length) {
      events.push(event);
    } else {
      events[eventIndex] = event;
    }

    return { ...chat, events };
  });
}

/**
 * Deprecated alias retained so existing imports keep building.
 * Use pushLocalChatEvent for new code.
 */
export const appendLocalChatEvent = pushLocalChatEvent;

export function saveLocalChatSession(chatId: string, session: SessionState) {
  updateChat(chatId, (chat) => ({ ...chat, session }));
}

export function saveLocalChatSnapshot({
  chatId,
  events,
  session,
}: {
  readonly chatId: string;
  readonly events: readonly HandleMessageStreamEvent[];
  readonly session: SessionState;
}) {
  updateChat(chatId, (chat) => ({
    ...chat,
    events,
    pendingUserMessage: null,
    session,
    updatedAt: new Date().toISOString(),
  }));
}

export function skipLocalChatAuthorization({
  chatId,
  events,
  session,
}: {
  readonly chatId: string;
  readonly events: readonly HandleMessageStreamEvent[];
  readonly session: SessionState;
}) {
  const chat = updateChat(chatId, (current) => ({
    ...current,
    events: [...current.events, ...events],
    pendingUserMessage: null,
    session,
    updatedAt: new Date().toISOString(),
  }));

  return {
    chat: toListItem(chat),
    eventCount: events.length,
    eventIndex: chat.events.length - events.length,
  };
}

function updateChat(chatId: string, update: (chat: StoredChat) => StoredChat) {
  const currentChat = readState().chats.find((chat) => chat.id === chatId);

  if (!currentChat) {
    throw new Error("Chat not found.");
  }

  const updatedChat = update(currentChat);

  updateState((chats) =>
    chats.map((chat) => (chat.id === chatId ? updatedChat : chat)),
  );

  return updatedChat;
}

function updateState(update: (chats: readonly StoredChat[]) => readonly StoredChat[]) {
  const nextChats = [...update(readState().chats)]
    .sort((left, right) => right.updatedAt.localeCompare(left.updatedAt))
    .slice(0, MAX_STORED_CHATS);

  try {
    localStorage.setItem(
      STORAGE_KEY,
      JSON.stringify({ chats: nextChats, version: STORAGE_VERSION } satisfies StoredChatState),
    );
  } catch {
    throw new Error("Browser storage is full. Delete an older chat and try again.");
  }
}

function readState(): StoredChatState {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);

    if (!raw) {
      return emptyState();
    }

    const parsed = JSON.parse(raw) as Partial<StoredChatState>;

    if (parsed.version !== STORAGE_VERSION || !Array.isArray(parsed.chats)) {
      return emptyState();
    }

    const chats = parsed.chats.filter(isStoredChat);

    return { chats, version: STORAGE_VERSION };
  } catch {
    return emptyState();
  }
}

function isStoredChat(value: unknown): value is StoredChat {
  if (!value || typeof value !== "object") {
    return false;
  }

  const chat = value as Partial<StoredChat>;

  return (
    typeof chat.id === "string" &&
    typeof chat.title === "string" &&
    typeof chat.updatedAt === "string" &&
    Array.isArray(chat.events)
  );
}

function toActiveChat(chat: StoredChat): ActiveChat {
  return {
    events: chat.events,
    id: chat.id,
    pendingUserMessage: chat.pendingUserMessage ?? null,
    session: chat.session,
    title: chat.title,
  };
}

function toListItem(chat: StoredChat): ChatListItem {
  return {
    id: chat.id,
    title: chat.title,
    updatedAt: chat.updatedAt,
  };
}

function emptyState(): StoredChatState {
  return { chats: [], version: STORAGE_VERSION };
}
"}],"concerns":["Removing appendLocalChatEvent outright while lib/chat/persistence-client.ts still imports it would break the build, so a deprecated alias was retained within the single allowed file to keep the repository building cleanly."],"rationale":"Renamed the implementation to pushLocalChatEvent while retaining a deprecated appendLocalChatEvent alias to preserve clean builds under single-file scope."}

{"files":[{"path":"lib/lore/certify.ts","content":"/**
 * sIVM certification worker: given a column's v_from -> v_to edit, decide
 * which cached v_from cells can be reused as v_to values with expected
 * false-reuse <= alpha (w.p. >= 1-delta), sampling only what the bound needs.
 *
 * The oracle (fresh v_to computation for sampled rows) is injectable so
 * experiments can serve it from a precomputed ground-truth table while
 * production serves it from the live runner. Every oracle call is counted;
 * that count IS the verification cost.
 */
import { randomUUID } from "node:crypto";
import {
  adaptiveCertifyStratum,
  assignStrata,
  diffPrompts,
  planSampleSizes,
  seededShuffle,
  selectReuse,
  type PromptDeltaV1,
  type SivmCellInput,
  type StratumResult,
} from "@lore/core/sivm";
import {
  applyCertificateReuse,
  getCellsForVersion,
  getColumnVersion,
  saveCertificate,
  type AiColumn,
} from "./column-store";
import { bindTemplate } from "./run-column";

type Row = Record<string, unknown>;

/** Returns fresh v_to values for the requested rows. */
export type Oracle = (rowIds: string[]) => Promise<Map<string, unknown>>;

export interface CertifyOptions {
  alpha: number;
  delta: number;
  /** Deterministic seed for the stratified sample (reproducibility). */
  seed?: number;
  /** Persist certificate + apply reuse rows (off for experiments). */
  apply?: boolean;
  /**
   * Grid-adaptive sampling: peek at a doubling look schedule (delta split
   * across looks, so peeking stays valid), stop early on certify or
   * futility. Unlocks small alpha without paying the worst-case sample.
   */
  adaptive?: boolean;
  /** Look-schedule depth for adaptive mode (default 4: 45/90/180/360). */
  maxLooks?: number;
  /**
   * Custom stratifier (e.g. embedding-interaction buckets). Must be frozen
   * before sampling; stratifier quality affects power only, never validity.
   */
  stratifier?: (
    cells: SivmCellInput[],
    delta: PromptDeltaV1,
  ) => ReturnType<typeof assignStrata>;
  /** Guarantee target: user-facing presented cells (default) or the strict
   * unsampled reuse set (deflated threshold). */
  estimand?: "presented" | "reuse-set";
}

export interface CertifyOutcome {
  certificateId: string;
  delta: PromptDeltaV1;
  strata: StratumResult[];
  sampledRowIds: string[];
  reusedRowIds: string[];
  recomputeRowIds: string[];
  oracleCalls: number;
  /** Sampled rows whose fresh value disagreed with cache (by stratum). */
  observedFlips: number;
}

function equivalent(a: unknown, b: unknown): boolean {
  // v1 equivalence: exact for booleans/selects/numbers-as-emitted; the
  // free-text judge path is a Phase 3 upgrade with its own calibrated error.
  return JSON.stringify(a) === JSON.stringify(b);
}

export async function verifyColumnEdit(
  column: AiColumn,
  fromVersion: number,
  toVersion: number,
  rows: Row[],
  idField: string,
  oracle: Oracle,
  opts: CertifyOptions,
): Promise<CertifyOutcome> {
  const vFrom = await getColumnVersion(column.id, fromVersion);
  const vTo = await getColumnVersion(column.id, toVersion);
  if (!vFrom || !vTo) throw new Error("missing column version");

  const delta = diffPrompts(vFrom.prompt_template, vTo.prompt_template);

  const rowById = new Map(rows.map((r) => [String(r[idField]), r]));
  const cached = await getCellsForVersion(column.id, fromVersion, [
    ...rowById.keys(),
  ]);
  const usable = cached.filter(
    (c) => (c.status === "done" || c.status === "cached") && rowById.has(c.row_id),
  );

  // Freeze strata from v_from cache + the prompt delta (pre-sampling).
  const inputs: SivmCellInput[] = usable.map((c) => ({
    rowId: c.row_id,
    cachedValue: c.value,
    boundText: bindTemplate(vFrom.prompt_template, rowById.get(c.row_id)!)
      .text,
  }));
  const strata = (opts.stratifier ?? assignStrata)(inputs, delta);
  const plan = planSampleSizes(
    strata.map((s) => ({ id: s.id, size: s.rowIds.length })),
    opts.alpha,
    opts.delta,
  );

  // Stratified deterministic sample order.
  const seed = opts.seed ?? 42;
  const cacheByRow = new Map(usable.map((c) => [c.row_id, c.value]));
  const fresh = new Map<string, unknown>();
  const revealed = new Set<string>();
  const reveal = async (rowIds: string[]) => {
    const need = rowIds.filter((id) => !revealed.has(id));
    if (need.length > 0) {
      const got = await oracle(need);
      for (const [k, v] of got) fresh.set(k, v);
      for (const id of need) revealed.add(id);
    }
  };

  let results: StratumResult[];
  const sampledByStratum = new Map<string, string[]>();

  if (opts.adaptive) {
    const K = Math.max(1, strata.length);
    const perStratumDelta = opts.delta / K;
    results = [];
    for (const s of strata) {
      const order = seededShuffle(s.rowIds, seed);
      const outcome = await adaptiveCertifyStratum(
        s.rowIds.length,
        opts.alpha,
        perStratumDelta,
        async (n) => {
          const prefix = order.slice(0, n);
          await reveal(prefix);
          return prefix
            .filter((id) => fresh.has(id))
            .map((id) =>
              equivalent(cacheByRow.get(id), fresh.get(id)) ? 0 : 1,
            );
        },
        45,
        opts.maxLooks ?? 4,
        opts.estimand ?? "presented",
      );
      sampledByStratum.set(s.id, order.slice(0, outcome.sampled));
      const last = outcome.looks[outcome.looks.length - 1]!;
      results.push({
        stratumId: s.id,
        size: s.rowIds.length,
        sampled: outcome.sampled,
        flips: last.flips,
        empiricalFlipRate: last.n > 0 ? last.flips / last.n : 1,
        upperBound: last.upperBound,
        certified: outcome.certified,
      });
    }
  } else {
    for (const s of strata) {
      const take = plan.get(s.id) ?? 0;
      sampledByStratum.set(s.id, seededShuffle(s.rowIds, seed).slice(0, take));
    }
    await reveal([...sampledByStratum.values()].flat());
    const mathInput = strata.map((s) => ({
      id: s.id,
      size: s.rowIds.length,
      flipSample: (sampledByStratum.get(s.id) ?? []).flatMap((rowId) => {
        if (!fresh.has(rowId)) return [];
        return [equivalent(cacheByRow.get(rowId), fresh.get(rowId)) ? 0 : 1];
      }),
    }));
    results = selectReuse({
      strata: mathInput,
      alpha: opts.alpha,
      delta: opts.delta,
    });
  }
  const sampledRowIds = [...sampledByStratum.values()].flat();

  const certifiedIds = new Set(
    results.filter((r) => r.certified).map((r) => r.stratumId),
  );
  const sampledSet = new Set(sampledRowIds);
  const reusedRowIds: string[] = [];
  const recomputeRowIds: string[] = [];
  for (const s of strata) {
    for (const rowId of s.rowIds) {
      // Sampled rows are already freshly computed - they are neither reused
      // nor recomputed again.
      if (sampledSet.has(rowId)) continue;
      if (certifiedIds.has(s.id)) reusedRowIds.push(rowId);
      else recomputeRowIds.push(rowId);
    }
  }

  const certificateId = randomUUID();
  if (opts.apply) {
    await saveCertificate({
      id: certificateId,
      columnId: column.id,
      fromVersion,
      toVersion,
      alpha: opts.alpha,
      delta,
      strata: results,
      reusedCount: reusedRowIds.length,
      recomputeCount: recomputeRowIds.length,
      sampledCount: sampledRowIds.length,
      verificationCostUsd: 0,
    });
    await applyCertificateReuse(
      column.id,
      fromVersion,
      toVersion,
      column.model,
      reusedRowIds,
      certificateId,
    );
  }

  return {
    certificateId,
    delta,
    strata: results,
    sampledRowIds,
    reusedRowIds,
    recomputeRowIds,
    oracleCalls: revealed.size,
    observedFlips: results.reduce((a, r) => a + r.flips, 0),
  };
}

/**
 * @deprecated Use `verifyColumnEdit` instead. Kept so existing importers
 * (e.g. app/api/lore/columns/[id]/certify/route.ts) keep building until
 * they are updated to the new name.
 */
export const certifyColumnEdit = verifyColumnEdit;
"}],"concerns":["app/api/lore/columns/[id]/certify/route.ts still imports certifyColumnEdit, so a pure rename in lib/lore/certify.ts alone would break the build; kept a deprecated alias in the same file to keep the build clean until the caller is updated."],"rationale":"Renamed implementation to verifyColumnEdit while keeping a deprecated alias so the existing importer keeps building."}

{"files":[{"path":"lib/db/client.ts","content":"import { neon } from "@neondatabase/serverless";
import { drizzle, type NeonHttpDatabase } from "drizzle-orm/neon-http";
import * as schema from "@/lib/db/schema";

let database: NeonHttpDatabase<typeof schema> | null = null;

export function hasDatabaseConfigured() {
  return Boolean(process.env.DATABASE_URL?.trim());
}

/**
 * @deprecated Use hasDatabaseConfigured instead.
 */
export const isDatabaseConfigured = hasDatabaseConfigured;

export function getDb() {
  if (!database) {
    const url = process.env.DATABASE_URL?.trim();

    if (!url) {
      throw new Error("DATABASE_URL is required. Add Neon to this Vercel project first.");
    }

    database = drizzle({ client: neon(url), schema });
  }

  return database;
}

export const db = new Proxy({} as NeonHttpDatabase<typeof schema>, {
  get(_, prop) {
    return (getDb() as unknown as Record<string | symbol, unknown>)[prop];
  },
});

export async function isDatabaseSchemaReady() {
  const url = process.env.DATABASE_URL?.trim();

  if (!url) {
    return false;
  }

  try {
    const sql = neon(url);
    const rows = (await sql`
      select
        to_regclass('public.account') is not null as account_ready,
        to_regclass('public.chat') is not null as chat_ready,
        to_regclass('public.chat_event') is not null as chat_event_ready,
        to_regclass('public.session') is not null as session_ready,
        to_regclass('public."user"') is not null as user_ready,
        to_regclass('public.verification') is not null as verification_ready
    `) as unknown as [
      {
        readonly account_ready: boolean;
        readonly chat_event_ready: boolean;
        readonly chat_ready: boolean;
        readonly session_ready: boolean;
        readonly user_ready: boolean;
        readonly verification_ready: boolean;
      },
    ];
    const result = rows[0];
    const ready = Boolean(
      result?.account_ready &&
        result.chat_ready &&
        result.chat_event_ready &&
        result.session_ready &&
        result.user_ready &&
        result.verification_ready,
    );

    return ready;
  } catch {
    return false;
  }
}
"}],"concerns":["lib/setup.ts still imports isDatabaseConfigured, so removing the old export outright would break the build; kept a deprecated isDatabaseConfigured alias for backward compatibility until callers are migrated in a follow-up."],"rationale":"Renamed to hasDatabaseConfigured while keeping a deprecated isDatabaseConfigured alias so existing callers keep building."}

